describe('Notification Auto-Dismiss Feature', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.viewport(1280, 720);
  });

  it('should auto-dismiss notification after 5 seconds', () => {
    // Trigger a notification
    cy.get('[data-testid="trigger-notification-btn"]').click();

    // Verify notification is visible
    cy.get('[data-testid="notification-container"]')
      .should('be.visible')
      .and('contain', 'Success');

    // Wait for 5 seconds and verify notification is dismissed
    cy.get('[data-testid="notification-container"]', { timeout: 6000 })
      .should('not.exist');
  });

  it('should dismiss notification immediately when close button is clicked', () => {
    // Trigger a notification
    cy.get('[data-testid="trigger-notification-btn"]').click();

    // Verify notification is visible
    cy.get('[data-testid="notification-container"]')
      .should('be.visible');

    // Click close button before 5 seconds
    cy.get('[data-testid="notification-close-btn"]')
      .should('be.visible')
      .click();

    // Verify notification is dismissed immediately
    cy.get('[data-testid="notification-container"]')
      .should('not.exist');
  });

  it('should handle multiple notifications with staggered dismissal', () => {
    // Trigger first notification
    cy.get('[data-testid="trigger-notification-btn"]').click();
    cy.get('[data-testid="notification-container"]').should('have.length', 1);

    // Wait 2 seconds and trigger second notification
    cy.wait(2000);
    cy.get('[data-testid="trigger-notification-btn"]').click();
    cy.get('[data-testid="notification-container"]').should('have.length', 2);

    // Wait 4 more seconds (6 total) - first notification should be gone
    cy.wait(4000);
    cy.get('[data-testid="notification-container"]').should('have.length', 1);

    // Wait 2 more seconds (8 total) - second notification should be gone
    cy.wait(2000);
    cy.get('[data-testid="notification-container"]').should('not.exist');
  });

  it('should reset dismiss timer when notification is interacted with', () => {
    // Trigger a notification
    cy.get('[data-testid="trigger-notification-btn"]').click();
    cy.get('[data-testid="notification-container"]')
      .should('be.visible');

    // Wait 4 seconds (before auto-dismiss)
    cy.wait(4000);

    // Interact with notification (hover or click action button)
    cy.get('[data-testid="notification-action-btn"]')
      .should('be.visible')
      .click();

    // Notification should still be visible after interaction
    cy.get('[data-testid="notification-container"]')
      .should('be.visible');

    // Wait another 3 seconds - should not dismiss yet if timer reset
    cy.wait(3000);
    cy.get('[data-testid="notification-container"]')
      .should('be.visible');

    // Wait final 2 seconds for total 5 from interaction
    cy.wait(2000);
    cy.get('[data-testid="notification-container"]')
      .should('not.exist');
  });

  it('should display different notification types with consistent dismiss timing', () => {
    const notificationTypes = ['success', 'error', 'warning', 'info'];

    notificationTypes.forEach((type) => {
      cy.get('[data-testid="notification-type-select"]').select(type);
      cy.get('[data-testid="trigger-notification-btn"]').click();

      cy.get('[data-testid="notification-container"]')
        .should('be.visible')
        .and('have.attr', 'data-notification-type', type);
    });

    // All notifications should be dismissed after 5 seconds
    cy.get('[data-testid="notification-container"]', { timeout: 6000 })
      .should('not.exist');
  });

  it('should handle rapid successive notification triggers', () => {
    // Trigger multiple notifications rapidly
    for (let i = 0; i < 5; i++) {
      cy.get('[data-testid="trigger-notification-btn"]').click();
    }

    // All notifications should be visible
    cy.get('[data-testid="notification-container"]').should('have.length', 5);

    // Wait 5 seconds for auto-dismiss
    cy.wait(5000);

    // All notifications should be dismissed
    cy.get('[data-testid="notification-container"]')
      .should('not.exist');
  });
});
